import{_ as d,o,c,a2 as t}from"./chunks/framework.DTwTvi8b.js";const u=JSON.parse('{"title":"步骤结果文件","description":"","frontmatter":{"editLink":false},"headers":[],"relativePath":"reference/contracts/result-file.md","filePath":"reference/contracts/result-file.md","lastUpdated":null}'),r={name:"reference/contracts/result-file.md"};function s(a,e,i,l,n,p){return o(),c("div",null,[...e[0]||(e[0]=[t('<div><h1 id="步骤结果文件" tabindex="-1">步骤结果文件 <a class="header-anchor" href="#步骤结果文件" aria-label="Permalink to &quot;步骤结果文件&quot;">​</a></h1><p>每个步骤结束时写一个 JSON 对象到 <code>.pipeline/results/&lt;步骤键&gt;.json</code>（路径在提示词的 <code>&lt;pipeline-context&gt;</code> 中给出）。引擎只根据它决定下一步，不读 agent 的回复文字。缺失或格式不对时，引擎会在同一个会话里提醒补写，最多 <code>resultFollowUps</code> 次（默认 2），仍不对则判定该步骤失败。</p><table tabindex="0"><thead><tr><th>步骤 ID</th><th>字段</th></tr></thead><tbody><tr><td><code>design</code></td><td><code>has_runnable_service</code>: boolean。可选（1.8 起）：<code>slices</code>: 字符串数组（实施计划的切片，按实现顺序；两片以上时按片逐个实现）；<code>files</code>: 字符串数组（预计改动的文件和目录，目录以 <code>/</code> 结尾，可用 <code>*</code>，用于范围检查）；缺陷类型的 <code>reproduced</code>: boolean，为 <code>false</code> 时 <code>questions</code>: 非空字符串数组（需要需求方补充的信息）；<code>ui_change</code>: boolean（改动是否改变使用者看到的界面或操作方式，方案确认点按它决定是否停下）</td></tr><tr><td><code>design_review</code></td><td><code>verdict</code>: <code>approved</code> | <code>changes_required</code> | <code>blocked</code>；为 <code>blocked</code> 时 <code>questions</code>: 非空字符串数组</td></tr><tr><td><code>design_revise</code></td><td><code>status</code>: <code>done</code> | <code>partial</code>。可选（1.8 起）：<code>slices</code>、<code>files</code>、<code>ui_change</code>，修订改变了它们时写新的值</td></tr><tr><td><code>implement</code></td><td><code>status</code>: <code>done</code> | <code>partial</code>。按切片实现时，每片的键为 <code>implement-s&lt;序号&gt;</code>。可选（1.8 起）：<code>acceptance_tests</code>: 字符串数组（从验收标准的例子写出、先单独提交的测试文件），<code>acceptance_tests_commit</code>: string（那次提交）；代码评审前引擎核对它们之后有没有被改过</td></tr><tr><td><code>review_fix</code>、<code>defect_fix</code></td><td><code>status</code>: <code>done</code> | <code>partial</code></td></tr><tr><td><code>code_review</code></td><td><code>verdict</code>: <code>pass</code> | <code>changes_required</code></td></tr><tr><td><code>service_start</code></td><td><code>started</code>: boolean</td></tr><tr><td><code>verify</code></td><td><code>result</code>: <code>pass</code> | <code>defects_found</code> | <code>blocked</code>。可选（1.8 起，联合需求）：<code>defect_repos</code>: 字符串数组，缺陷所在的仓库（<code>本仓库</code> 或 <code>relatedRepos</code> 中的名称）；没有时每个仓库都做一轮缺陷修复</td></tr><tr><td><code>reverify</code></td><td><code>result</code>: <code>pass</code> | <code>defects_remaining</code>。可选：<code>defect_repos</code>，同上</td></tr><tr><td><code>report</code></td><td><code>outcome</code>: <code>completed</code> | <code>completed_with_issues</code> | <code>not_completed</code>；<code>summary</code>: string</td></tr><tr><td><code>panel_review</code>（评审小组成员，键为 <code>&lt;评审步骤&gt;-r&lt;轮次&gt;-p&lt;序号&gt;</code>）</td><td><code>status</code>: <code>done</code> | <code>partial</code>；意见写在 <code>&lt;功能目录&gt;/review-panel/&lt;键&gt;.md</code></td></tr></tbody></table><p>联合需求中，其他仓库的步骤的键带 <code>@&lt;仓库后缀&gt;</code>（如 <code>implement@backend</code>、<code>code_review-r2@backend</code>），结果文件写在那个仓库工作区的功能目录中。</p><p>字段定义以 <code>engine/src/steps.ts</code> 为准；改动时同步更新各步骤提示词末尾的&quot;结果文件&quot;一节。</p></div><p class="source-note">本页由仓库中的 <a href="https://github.com/yiyisf/paseo-req-kit/blob/main/contracts/result-file.md">contracts/result-file.md</a> 生成。<a href="https://github.com/yiyisf/paseo-req-kit/edit/main/contracts/result-file.md">在 GitHub 上编辑</a></p>',2)])])}const f=d(r,[["render",s]]);export{u as __pageData,f as default};
